1	---
2	// ProjectLayout.astro — wraps an individual project's case-study page.
3	// Adapted from BlogLayout.astro: swaps the date+tags meta row for a single
4	// icon+eyebrow badge, and adds a Role/Scope properties row plus a Loom embed
5	// (hidden until the reader opts in via "Watch the overview") that articles
6	// don't have.
7	import BaseLayout from "./BaseLayout.astro";
8	import Lightbox from "@/components/Lightbox.astro";
9	import PillButton from "@/components/case-study/PillButton.astro";
10	import { Home } from "pixelarticons/react/Home";
11	import { Play } from "pixelarticons/react/Play";
12	import type { ComponentType, SVGProps } from "react";
13	
14	interface Props {
15	  name: string;
16	  tagline: string;
17	  icon: ComponentType<SVGProps<SVGSVGElement>>;
18	  iconColor?: string;
19	  iconColorDark?: string;
20	  badgeColor?: string;
21	  badgeColorDark?: string;
22	  description?: string;
23	  accentPhrase?: string;
24	  loomUrl?: string;
25	  role?: string;
26	  scope?: string;
27	}
28	
29	const {
30	  name,
31	  tagline,
32	  icon,
33	  iconColor,
34	  iconColorDark,
35	  badgeColor,
36	  badgeColorDark,
37	  description,
38	  accentPhrase,
39	  loomUrl,
40	  role,
41	  scope,
42	} = Astro.props;
43	
44	// Dek paragraph (the 24px intro copy under the headline) prefers the longer
45	// `description`, falling back to the shorter home-page-list `tagline` when a
46	// case study hasn't set one yet.
47	const dek = description ?? tagline;
48	
49	// Same split-around-a-phrase technique as BlogLayout's accentWord, but
50	// colored by the project's own iconColor rather than a shared category
51	// config. Applied to `tagline` (the headline text), not `dek` — the
52	// headline and the intro paragraph below it are two separate strings.
53	const accentIndex = accentPhrase ? tagline.indexOf(accentPhrase) : -1;
54	const taglineBefore =
55	  accentIndex >= 0 ? tagline.slice(0, accentIndex) : tagline;
56	const taglineAfter =
57	  accentIndex >= 0
58	    ? tagline.slice(accentIndex + (accentPhrase?.length ?? 0))
59	    : "";
60	
61	// Loom share URLs (loom.com/share/<id>) don't render embedded — the player
62	// requires the /embed/<id> path.
63	const embedSrc = loomUrl?.replace("/share/", "/embed/");
64	
65	// JSX/Astro only renders a variable as a component if it starts with a
66	// capital letter — `icon` comes in lowercase as a prop, so it needs a
67	// capitalized alias before it can be used as `<Icon />` below.
68	const Icon = icon;
69	---
70	
71	<BaseLayout title={name} description={tagline}>
72	  {
73	    /* Warms up the connection to Loom's domains as soon as the page loads,
74	      instead of paying full DNS+TLS+redirect latency at the moment the
75	      reader clicks "Watch the overview". Rendered into BaseLayout's named
76	      "head" slot — a <link> in the default slot stays in <body> where
77	      it's written, it isn't auto-hoisted to <head> the way <style>/<script>
78	      tags are. */
79	  }
80	  {
81	    embedSrc && (
82	      <Fragment slot="head">
83	        <link rel="preconnect" href="https://www.loom.com" />
84	        <link rel="preconnect" href="https://cdn.loom.com" crossorigin />
85	      </Fragment>
86	    )
87	  }
88	  <main class="mx-auto max-w-[1120px] py-18">
89	    <article class="px-6 sm:px-10 lg:px-[60px]">
90	      <header data-animate class="mb-12 flex flex-col gap-8">
91	        {
92	          /* Breadcrumb: Home badge, then the project's own icon badge + eyebrow label
93	            (that project badge/label markup matches the home page's Work list rows) */
94	        }
95	        <div class="flex items-center gap-4">
96	          <a href="/" class="flex items-center gap-2">
97	            <span
98	              class="bg-portfolio-muted/15 flex size-7 items-center justify-center rounded-md"
99	            >
100	              <Home width={16} height={16} className="text-portfolio-muted" />
101	            </span>
102	            <span class="text-portfolio-muted font-mono text-base underline"
103	              >Home</span
104	            >
105	          </a>
106	          <span class="text-portfolio-muted">•</span>
107	          <div class="flex items-center gap-2">
108	            <span
109	              class="flex size-7 shrink-0 items-center justify-center rounded-md"
110	              style={{
111	                backgroundColor: "var(--badge-color)",
112	                ...(badgeColor ? { "--badge-color-light": badgeColor } : {}),
113	                ...(badgeColorDark
114	                  ? { "--badge-color-dark": badgeColorDark }
115	                  : {}),
116	              }}
117	            >
118	              <Icon
119	                width={16}
120	                height={16}
121	                style={{
122	                  color: "var(--icon-color)",
123	                  ...(iconColor ? { "--icon-color-light": iconColor } : {}),
124	                  ...(iconColorDark
125	                    ? { "--icon-color-dark": iconColorDark }
126	                    : {}),
127	                }}
128	              />
129	            </span>
130	            <p
131	              class="text-portfolio-ink font-mono text-base tracking-[-0.18px]"
132	            >
133	              {name}
134	            </p>
135	          </div>
136	        </div>
137	
138	        {
139	          /* Headline — accentPhrase (if set) renders italicized in the project's own iconColor.
140	            .portfolio-headline (global.css) is the shared big-title treatment
141	            every headline on the site uses (home page, blog posts, case
142	            studies), including its fluid clamp() font-size. */
143	        }
144	        <h1 class="portfolio-headline">
145	          {taglineBefore}
146	          {
147	            accentIndex >= 0 && (
148	              <span
149	                class="italic"
150	                style={{
151	                  color: "var(--icon-color)",
152	                  ...(iconColor ? { "--icon-color-light": iconColor } : {}),
153	                  ...(iconColorDark
154	                    ? { "--icon-color-dark": iconColorDark }
155	                    : {}),
156	                }}
157	              >
158	                {accentPhrase}
159	              </span>
160	            )
161	          }
162	          {taglineAfter}
163	        </h1>
164	      </header>
165	
166	      {
167	        /* Body — same max-width and typography as the article template's body column */
168	      }
169	      <div data-animate class="flex flex-col gap-10">
170	        <p class="font-plex-sans text-portfolio-ink text-2xl leading-10">
171	          {dek}
172	        </p>
173	
174	        {
175	          (embedSrc || role || scope) && (
176	            <div class="flex flex-col gap-10">
177	              {/* Properties row: overview toggle + Role/Scope, all optional so
178	                a case study can omit any of them. The toggle now opens the
179	                shared Lightbox (rendered once below) instead of an inline
180	                accordion — clicking it is just another lightbox trigger,
181	                identified to Lightbox.astro's delegated listener the same
182	                way a case-study image is (see LightboxImage.astro). */}
183	              <div class="flex flex-wrap items-start gap-10">
184	                {embedSrc && (
185	                  <PillButton
186	                    id="overview-toggle"
187	                    icon={Play}
188	                    label="Watch the overview"
189	                    iconColor="oklch(54.6% 0.245 262.881)"
190	                    background="color-mix(in oklch, oklch(54.6% 0.245 262.881) 15%, transparent)"
191	                    data-lightbox-trigger
192	                    data-lightbox-type="iframe"
193	                    data-lightbox-src={embedSrc}
194	                  />
195	                )}
196	
197	                {role && (
198	                  <div class="flex flex-col gap-1 font-mono text-sm tracking-[-0.14px]">
199	                    <p class="text-portfolio-muted">Role</p>
200	                    <p class="text-portfolio-ink whitespace-nowrap">{role}</p>
201	                  </div>
202	                )}
203	
204	                {scope && (
205	                  <div class="flex min-w-[240px] flex-1 flex-col gap-1 font-mono text-sm tracking-[-0.14px]">
206	                    <p class="text-portfolio-muted">Scope</p>
207	                    <p class="text-portfolio-ink">{scope}</p>
208	                  </div>
209	                )}
210	              </div>
211	            </div>
212	          )
213	        }
214	
215	        {/* Rest of the MDX body */}
216	        <div
217	          class="article-body font-plex-sans text-portfolio-ink text-base leading-8"
218	        >
219	          <slot />
220	        </div>
221	      </div>
222	    </article>
223	  </main>
224	
225	  <Lightbox />
226	</BaseLayout>
227	
228	<style>
229	  /* MDX content comes from a separately-compiled component tree (rendered via
230	     <Content /> in [slug].astro), so Astro's default *scoped* styles never
231	     attach to it — every rule here needs :global() or it silently does nothing.
232	     Mirrors BlogLayout.astro's identical block. */
233	  /* Two separate spacing tokens, easy to conflate but serving different
234	     jobs:
235	       --ping-section-gap   — vertical rhythm BETWEEN sections. Stays a
236	                               fixed 60px at every viewport width — this is
237	                               breathing room in the reading flow, not
238	                               something that should compress on mobile.
239	       --ping-card-padding   — the INSET inside a bordered/gradient card
240	                               (Problem/Approach/Solution) and the
241	                               <article> wrapper's own horizontal margin.
242	                               This one DOES scale down on narrow screens
243	                               (24px mobile / 40px tablet / 60px desktop,
244	                               matching <article>'s own
245	                               px-6 sm:px-10 lg:px-[60px]) — a flat 60px
246	                               inset squished the readable column badly on
247	                               phones. Collapsing both into one variable
248	                               previously made the inter-section gap shrink
249	                               along with the card padding, which read as
250	                               sections crowding each other on mobile. */
251	  .article-body {
252	    --ping-section-gap: 3.75rem; /* 60px, fixed at every width */
253	    --ping-card-padding: 1.5rem; /* 24px */
254	  }
255	
256	  @media (min-width: 40rem) {
257	    .article-body {
258	      --ping-card-padding: 2.5rem; /* 40px */
259	    }
260	  }
261	
262	  @media (min-width: 64rem) {
263	    .article-body {
264	      --ping-card-padding: 3.75rem; /* 60px */
265	    }
266	  }
267	
268	  /* Each top-level block in the MDX body is wrapped in its own
269	     `.ping-section`, so this gap can sit on both sides of a section as
270	     real padding (padding needs a real box on each edge — a
271	     margin-collapse-via-adjacency-selector approach only works for a flat
272	     list of siblings, and margin between siblings COLLAPSES rather than
273	     stacking, which reads as inconsistent spacing once some sections also
274	     have their own border/background — a card's edge should have a
275	     definite, non-collapsing gap around it). The first section only gets
276	     bottom padding, matching Figma's Intro frame using pb-[60px] instead
277	     of py-[60px] since there's nothing above it to pad against.
278	     Problem/Approach/Solution below add their own padding-LEFT/RIGHT only
279	     (not the `padding` shorthand) — the shorthand would overwrite this
280	     rule's padding-top/-bottom outright, since both rules have equal
281	     specificity and the later one wins on every side it touches. Setting
282	     only the two horizontal longhands here means their own left/right
283	     inset composes with (rather than replaces) this rule's vertical gap. */
284	  .article-body :global(.ping-section) {
285	    padding-top: var(--ping-section-gap);
286	    padding-bottom: var(--ping-section-gap);
287	  }
288	
289	  .article-body :global(.ping-section:first-child) {
290	    padding-top: 0;
291	  }
292	
293	  /* "The problem" gets a plain 1px stroke outline and its own left/right
294	     inset (on top of the padding-top/-bottom every section already has
295	     from the rule above) — the one section styled as a bordered card
296	     rather than a plain full-bleed block. padding-top/-bottom here
297	     re-declare --ping-section-gap (the FIXED token), not
298	     --ping-card-padding (the responsive one) — using the responsive
299	     variable for the vertical sides was the exact bug this replaced:
300	     it made this section's vertical gap shrink along with its horizontal
301	     inset on mobile, instead of staying fixed like every other section's. */
302	  .article-body :global(.ping-section--problem) {
303	    border: 1px solid var(--section-border-color);
304	    border-radius: 0.75rem; /* 12px */
305	    padding-top: var(--ping-section-gap);
306	    padding-bottom: var(--ping-section-gap);
307	    padding-left: var(--ping-card-padding);
308	    padding-right: var(--ping-card-padding);
309	    margin-top: var(--ping-card-padding);
310	    margin-bottom: var(--ping-card-padding);
311	  }
312	
313	  /* "The approach" gets the same left/right inset, matching "The problem"
314	     above — vertical padding stays on the fixed --ping-section-gap for
315	     the same reason. */
316	  .article-body :global(.ping-section--approach) {
317	    padding-top: var(--ping-section-gap);
318	    padding-bottom: var(--ping-section-gap);
319	    padding-left: var(--ping-card-padding);
320	    padding-right: var(--ping-card-padding);
321	  }
322	
323	  /* "The solution" gets a translucent border and a subtle vertical-fade
324	     background, both tinted by the project's own --icon-color (set inline
325	     in the MDX, resolved the same way the headline accent and Postscript's
326	     divider already do) — so each case study gets a matching treatment in
327	     its own accent color instead of every project showing Ping's red.
328	     color-mix() against transparent is what lets a var()-sourced color
329	     carry a percentage opacity — CSS's plain `color / alpha%` syntax only
330	     accepts a literal color, not a custom property. */
331	  .article-body :global(.ping-section--solution) {
332	    border-radius: 0.75rem; /* 12px */
333	    padding-top: var(--ping-section-gap);
334	    padding-bottom: var(--ping-section-gap);
335	    padding-left: var(--ping-card-padding);
336	    padding-right: var(--ping-card-padding);
337	    margin-top: var(--ping-card-padding);
338	    margin-bottom: var(--ping-card-padding);
339	    border: 1px solid color-mix(in oklch, var(--icon-color) 50%, transparent);
340	    background: linear-gradient(
341	      0deg,
342	      color-mix(in oklch, var(--icon-color) 0%, transparent) 0%,
343	      color-mix(in oklch, var(--icon-color) 13%, transparent) 100%
344	    );
345	    background-origin: border-box;
346	    background-clip: padding-box, padding-box, border-box;
347	  }
348	
349	  /* A heading still sits close to the content directly under it (16px),
350	     same as Figma's "The problem"/"The approach" heading+paragraph groups —
351	     this is intra-section spacing, unaffected by the section padding above. */
352	  .article-body :global(h2 + *) {
353	    margin-top: 1rem; /* 16px */
354	  }
355	
356	  .article-body :global(h2) {
357	    font-family: var(--font-plex-sans);
358	    font-weight: 500;
359	    font-size: 1.5rem; /* 24px */
360	    line-height: 2.5rem; /* 40px */
361	    color: var(--portfolio-ink);
362	  }
363	
364	  .article-body :global(p) {
365	    font-family: var(--font-plex-sans);
366	    font-size: 1.125rem; /* 18px */
367	    line-height: 2rem; /* 32px */
368	    font-weight: 300;
369	  }
370	
371	  /* Paragraphs immediately following another paragraph (e.g. "The problem"'s
372	     three-paragraph run) sit tighter than the 40px inter-block gap above —
373	     Figma treats runs of body copy as one 16px-spaced group. */
374	  .article-body :global(p + p) {
375	    margin-top: 1rem; /* 16px */
376	  }
377	
378	  /* Every `.ping-section` in Figma is a `flex flex-col gap-[40px]` —
379	     Intro's paragraphs vs. its image, Approach's copy vs. its two-image row,
380	     a Point's LabeledRow vs. its LoopVideo, all 40px apart regardless of
381	     element type. This is intra-section spacing between a section's direct
382	     children, distinct from `.ping-section`'s own 60px outer padding above.
383	     `:not(p)` keeps this from overriding the tighter 16px `p + p` run
384	     spacing below — a `p` following a `p` should stay at 16px, not jump to
385	     40px just because both happen to sit inside a `.ping-section`. */
386	  .article-body :global(.ping-section > * + *:not(p)) {
387	    margin-top: 2.5rem; /* 40px */
388	  }
389	
390	  .article-body :global(a) {
391	    color: inherit;
392	    text-decoration: underline;
393	    text-decoration-skip-ink: none;
394	    text-underline-position: from-font;
395	  }
396	</style>
